using System;
using System.Linq;
using System.Drawing;
using System.Collections.Generic;

public static class MapRouting {
 public static string Side(MapNode n,MapNode other){float dx=other.X+other.Width/2-n.X-n.Width/2,dy=other.Y+other.Height/2-n.Y-n.Height/2;bool horizontal=other.X>=n.X+n.Width||n.X>=other.X+other.Width;bool vertical=other.Y>=n.Y+n.Height||n.Y>=other.Y+other.Height;if(horizontal&&!vertical)return dx>0?"Right":"Left";if(vertical&&!horizontal)return dy>0?"Bottom":"Top";return Math.Abs(dx)>Math.Abs(dy)?(dx>0?"Right":"Left"):(dy>=0?"Bottom":"Top");}
 public static PointF Socket(MapNode n,string side,float fraction=.5f){return side=="Left"?new PointF(n.X,n.Y+n.Height*fraction):side=="Right"?new PointF(n.X+n.Width,n.Y+n.Height*fraction):side=="Top"?new PointF(n.X+n.Width*fraction,n.Y):new PointF(n.X+n.Width*fraction,n.Y+n.Height);}
 static MapNode Node(NetworkMap map,string id){return map.Nodes.First(n=>n.Id==id);}
 public static string SideAt(NetworkMap map,MapLink link,string id){string fixedSide=link.From==id?link.FromSide:link.ToSide;return String.IsNullOrEmpty(fixedSide)?Side(Node(map,id),Node(map,link.From==id?link.To:link.From)):fixedSide;}
 static List<MapLink> Group(NetworkMap map,string id,string side){return map.Links.Where(l=>(l.From==id||l.To==id)&&SideAt(map,l,id)==side).OrderBy(l=>(l.From==id?l.FromOrder:l.ToOrder)<0?1:0).ThenBy(l=>{int order=l.From==id?l.FromOrder:l.ToOrder;if(order>=0)return (float)order;var other=Node(map,l.From==id?l.To:l.From);return side=="Left"||side=="Right"?other.Y+other.Height/2:other.X+other.Width/2;}).ThenBy(l=>l.Id,StringComparer.Ordinal).ToList();}
 public static PointF End(NetworkMap map,MapLink link,bool from){string id=from?link.From:link.To;var n=Node(map,id);string side=SideAt(map,link,id);var group=Group(map,id,side);return Socket(n,side,(group.IndexOf(link)+1f)/(group.Count+1));}
 // Pin all endpoints in the affected side's order, so later node moves cannot shuffle ports.
 public static void ReorderEnd(NetworkMap map,MapLink link,bool from,string side,PointF drop){string id=from?link.From:link.To;var group=Group(map,id,side);float axis=side=="Left"||side=="Right"?drop.Y:drop.X;int insert=0;foreach(var l in group){if(l==link)continue;var end=End(map,l,l.From==id);if((side=="Left"||side=="Right"?end.Y:end.X)<axis)insert++;}group.Remove(link);group.Insert(insert,link);for(int i=0;i<group.Count;i++){var l=group[i];if(l.From==id){l.FromSide=side;l.FromOrder=i;}else{l.ToSide=side;l.ToOrder=i;}}}
 public static string NearestSide(MapNode n,PointF p){return new[]{"Top","Right","Bottom","Left"}.OrderBy(side=>side=="Top"?Math.Abs(p.Y-n.Y):side=="Bottom"?Math.Abs(p.Y-n.Y-n.Height):side=="Left"?Math.Abs(p.X-n.X):Math.Abs(p.X-n.X-n.Width)).First();}
 public static PointF[] Manual(NetworkMap map,MapLink l){var a=End(map,l,true);var b=End(map,l,false);var first=l.ManualRoute[0];var last=l.ManualRoute[l.ManualRoute.Count-1];bool horizontal=SideAt(map,l,l.From)=="Left"||SideAt(map,l,l.From)=="Right";bool endHorizontal=SideAt(map,l,l.To)=="Left"||SideAt(map,l,l.To)=="Right";return Clean(new[]{a,horizontal?new PointF(first.X,a.Y):new PointF(a.X,first.Y)}.Concat(l.ManualRoute.Select(p=>new PointF(p.X,p.Y))).Concat(new[]{endHorizontal?new PointF(last.X,b.Y):new PointF(b.X,last.Y),b}));}
 public static List<MapPoint> MoveSegment(PointF[] route,int index,float coordinate){var points=route.ToList();bool horizontal=points[index].Y==points[index+1].Y;var a=points[index];var b=points[index+1];var shiftedA=horizontal?new PointF(a.X,coordinate):new PointF(coordinate,a.Y);var shiftedB=horizontal?new PointF(b.X,coordinate):new PointF(coordinate,b.Y);
  // Keep the original end stubs attached even when the first/last segment is dragged.
  if(index==0){var stub=new PointF(a.X+(b.X-a.X)*.15f,a.Y+(b.Y-a.Y)*.15f);points.Insert(1,stub);index++;a=stub;shiftedA=horizontal?new PointF(a.X,coordinate):new PointF(coordinate,a.Y);points.Insert(index+1,shiftedA);index++;}else points[index]=shiftedA;
  if(index+1==points.Count-1){var stub=new PointF(b.X+(a.X-b.X)*.15f,b.Y+(a.Y-b.Y)*.15f);shiftedB=horizontal?new PointF(stub.X,coordinate):new PointF(coordinate,stub.Y);points.Insert(index+1,shiftedB);points.Insert(index+2,stub);}else points[index+1]=shiftedB;
  var clean=Clean(points);return clean.Skip(1).Take(clean.Length-2).Select(p=>new MapPoint{X=p.X,Y=p.Y}).ToList();}
 static PointF Out(PointF p,string side){return new PointF(p.X+(side=="Left"?-20:side=="Right"?20:0),p.Y+(side=="Top"?-20:side=="Bottom"?20:0));}
 static bool Obstacle(PointF a,PointF b,RectangleF r){if(a.X==b.X)return a.X>r.Left&&a.X<r.Right&&Math.Max(a.Y,b.Y)>r.Top&&Math.Min(a.Y,b.Y)<r.Bottom;return a.Y>r.Top&&a.Y<r.Bottom&&Math.Max(a.X,b.X)>r.Left&&Math.Min(a.X,b.X)<r.Right;}
 static int Conflict(PointF a,PointF b,PointF c,PointF d){bool av=a.X==b.X,cv=c.X==d.X;if(av!=cv){var v=av?a:c;var v2=av?b:d;var h=av?c:a;var h2=av?d:b;return v.X>Math.Min(h.X,h2.X)&&v.X<Math.Max(h.X,h2.X)&&h.Y>Math.Min(v.Y,v2.Y)&&h.Y<Math.Max(v.Y,v2.Y)?1:0;}if(av)return Math.Abs(a.X-c.X)<14&&Math.Min(Math.Max(a.Y,b.Y),Math.Max(c.Y,d.Y))-Math.Max(Math.Min(a.Y,b.Y),Math.Min(c.Y,d.Y))>4?2:0;return Math.Abs(a.Y-c.Y)<14&&Math.Min(Math.Max(a.X,b.X),Math.Max(c.X,d.X))-Math.Max(Math.Min(a.X,b.X),Math.Min(c.X,d.X))>4?2:0;}
 static PointF[] Clean(IEnumerable<PointF> points){var r=new List<PointF>();foreach(var p in points){if(r.Count>0&&r[r.Count-1]==p)continue;while(r.Count>=2&&((r[r.Count-2].X==r[r.Count-1].X&&r[r.Count-1].X==p.X)||(r[r.Count-2].Y==r[r.Count-1].Y&&r[r.Count-1].Y==p.Y))){var a=r[r.Count-2];var b=r[r.Count-1];if((b.X-a.X)*(p.X-b.X)+(b.Y-a.Y)*(p.Y-b.Y)<0)break;r.RemoveAt(r.Count-1);}r.Add(p);}return r.ToArray();}
 public static Dictionary<string,PointF[]> Build(NetworkMap map){var routes=new Dictionary<string,PointF[]>();foreach(var link in map.Links.OrderBy(l=>l.ManualRoute.Count>0?0:1).ThenBy(l=>l.Id,StringComparer.Ordinal)){if(link.ManualRoute.Count>0){routes[link.Id]=Manual(map,link);continue;}var n=Node(map,link.From);var m=Node(map,link.To);var a=End(map,link,true);var b=End(map,link,false);var aa=Out(a,SideAt(map,link,link.From));var bb=Out(b,SideAt(map,link,link.To));var candidates=new List<PointF[]>();Action<PointF[]> add=mid=>candidates.Add(Clean(new[]{a,aa}.Concat(mid).Concat(new[]{bb,b})));
  add(new[]{new PointF(aa.X,bb.Y)});add(new[]{new PointF(bb.X,aa.Y)});
  var xs=new List<float>{(aa.X+bb.X)/2};var ys=new List<float>{(aa.Y+bb.Y)/2};foreach(var node in map.Nodes){xs.Add(node.X-32);xs.Add(node.X+node.Width+32);ys.Add(node.Y-32);ys.Add(node.Y+node.Height+32);}var used=routes.Values.SelectMany(p=>p).ToList();foreach(float x in used.SelectMany(p=>new[]{p.X-16,p.X+16}).Distinct().OrderBy(x=>Math.Abs(x-(aa.X+bb.X)/2)).Take(32))xs.Add(x);foreach(float y in used.SelectMany(p=>new[]{p.Y-16,p.Y+16}).Distinct().OrderBy(y=>Math.Abs(y-(aa.Y+bb.Y)/2)).Take(32))ys.Add(y);foreach(float x in xs.Distinct())add(new[]{new PointF(x,aa.Y),new PointF(x,bb.Y)});foreach(float y in ys.Distinct())add(new[]{new PointF(aa.X,y),new PointF(bb.X,y)});
  double best=double.MaxValue;PointF[] chosen=null;foreach(var p in candidates){double score=p.Length*9;for(int i=1;i<p.Length;i++){score+=Math.Abs(p[i].X-p[i-1].X)+Math.Abs(p[i].Y-p[i-1].Y);foreach(var node in map.Nodes){var r=new RectangleF(node.X-6,node.Y-6,node.Width+12,node.Height+12);if(node.Id==n.Id||node.Id==m.Id)r=new RectangleF(node.X,node.Y,node.Width,node.Height);if(Obstacle(p[i-1],p[i],r))score+=1000000;}foreach(var old in routes.Values)for(int j=1;j<old.Length;j++)score+=Conflict(p[i-1],p[i],old[j-1],old[j])*450;}if(score<best){best=score;chosen=p;}}routes[link.Id]=chosen;
 }return routes;}
}
